    ("ipv4-df-blackhole", "Small traffic works while a large DF datagram stalls", "A sender emits a 1500-byte IPv4 datagram with DF set toward a 1400-byte output link. The router drops it and generates eligible fragmentation-needed feedback; if that feedback is filtered and the sender keeps the old size without fallback, smaller packets can still succeed while the larger transfer stalls.", ["dont-fragment", "oversized", "fragmentation-needed", "icmp-filter", "pmtu-blackhole"]),
    ("ipv6-feedback-floor", "Do not repair a bogus small PTB by clamping", "An IPv6 sender currently estimates 1500 bytes. Valid applicable PTB feedback reporting 1400 can reduce that estimate; a PTB reporting 1000 must instead be discarded under RFC 8201's IPv6-minimum rule, without manufacturing a 1280-byte update from it.", ["packet-too-big", "pmtu-estimate", "smaller-packets"]),
    ("tunnel-size-budget", "Outer headers consume the available MTU", "An inner IP packet is 1480 bytes and the actual tunnel adds 40 bytes before an outer link with IP MTU 1500. The resulting 1520-byte outer packet exceeds that link's budget; packetization or permitted source/router fragmentation must account for the extra layer.", ["encapsulation", "output-mtu", "oversized", "smaller-packets"]),
